#![cfg(test)]
extern crate std;
use super::*;
use soroban_sdk::{Bytes, Env, U256};

/// tests/vetores-poseidon.json, generated by circuits/vetores_poseidon.mjs from
/// circomlibjs — the same Poseidon the circuit uses (Q-22).
///
/// The path and the JSON keys are still Portuguese: the vector files are
/// renamed and regenerated in one step of T-058, together with every reader.
const VECTORS: &str = include_str!("../../../tests/vetores-poseidon.json");

fn u256(env: &Env, h: &str) -> U256 {
    let h = h.trim_start_matches("0x");
    let mut b = [0u8; 32];
    for i in 0..32 {
        b[i] = u8::from_str_radix(&h[2 * i..2 * i + 2], 16).unwrap();
    }
    U256::from_be_bytes(env, &Bytes::from_array(env, &b))
}

fn vectors() -> std::vec::Vec<(std::vec::Vec<std::string::String>, std::string::String)> {
    let j: serde_json::Value = serde_json::from_str(VECTORS).unwrap();
    j["vetores"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| {
            let e = v["entradas"]
                .as_array()
                .unwrap()
                .iter()
                .map(|x| x.as_str().unwrap().into())
                .collect();
            (e, v["saida"].as_str().unwrap().into())
        })
        .collect()
}

#[test]
fn there_are_at_least_twenty_one_and_two_input_vectors() {
    let vs = vectors();
    let one = vs.iter().filter(|(e, _)| e.len() == 1).count();
    let two = vs.iter().filter(|(e, _)| e.len() == 2).count();
    assert!(one + two >= 20, "the SPEC asks for at least 20");
    assert!(one >= 1 && two >= 1);
    assert_eq!(one + two, vs.len());
}

/// Q-22: the sponge over the host permutation returns, byte for byte, what
/// circomlibjs returns.
#[test]
fn matches_circomlib() {
    let env = Env::default();
    for (i, (e, s)) in vectors().iter().enumerate() {
        let got = match e.len() {
            1 => hash1(&env, &u256(&env, &e[0])),
            2 => hash2(&env, &u256(&env, &e[0]), &u256(&env, &e[1])),
            _ => unreachable!(),
        };
        assert_eq!(got, u256(&env, s), "vector {} ({:?})", i, e);
    }
}

/// An input outside the field is refused, not reduced: without that, `x` and
/// `x + r` would give the same hash.
#[test]
#[should_panic]
fn an_input_outside_the_field_is_refused() {
    let env = Env::default();
    let r = u256(
        &env,
        "0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001",
    );
    hash1(&env, &r);
}

/// Cost measured in the test host (`env.cost_estimate().budget()`), not in a
/// testnet transaction. If the cost changes, this test goes red (G2).
/// `(cpu, mem)`: one hash1 with a fresh sponge, one hash2 with a fresh sponge,
/// and the whole depth-6 tree — 64 Poseidon(1) leaves and 63 Poseidon(2)
/// nodes, with both sponges built once (T-035).
const HASH1_COST: (u64, u64) = (1_001_368, 57_296);
const HASH2_COST: (u64, u64) = (1_454_641, 81_832);
const TREE_6_COST: (u64, u64) = (109_821_216, 3_373_240);

fn measure(env: &Env, f: impl FnOnce()) -> (u64, u64) {
    env.cost_estimate().budget().reset_unlimited();
    f();
    let b = env.cost_estimate().budget();
    (b.cpu_instruction_cost(), b.memory_bytes_cost())
}

#[test]
fn measured_cost() {
    let env = Env::default();
    let x = U256::from_u32(&env, 11);
    let h1 = measure(&env, || {
        hash1(&env, &x);
    });
    let h2 = measure(&env, || {
        hash2(&env, &x, &x);
    });
    let tree = measure(&env, || {
        let s2 = Sponge::t2(&env);
        let s3 = Sponge::t3(&env);
        let mut level: std::vec::Vec<U256> = (0..64u32)
            .map(|i| s2.hash(&soroban_sdk::vec![&env, U256::from_u32(&env, i)]))
            .collect();
        while level.len() > 1 {
            level = level
                .chunks(2)
                .map(|p| s3.hash(&soroban_sdk::vec![&env, p[0].clone(), p[1].clone()]))
                .collect();
        }
    });
    std::println!("hash1 {:?}  hash2 {:?}  tree6 {:?}", h1, h2, tree);
    assert_eq!(h1, HASH1_COST, "hash1 (cpu, mem)");
    assert_eq!(h2, HASH2_COST, "hash2 (cpu, mem)");
    assert_eq!(tree, TREE_6_COST, "depth-6 tree (cpu, mem)");
}
